"use client"

import React from "react"
import {
    Link,
    Typography,
    cn,
} from "@heroui/react"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import type { VerdictBand } from "@/components/blocks/cards/verdict-band"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { UserCell } from "@/components/composites/lists/UserCell"
import {
    placeMedalIcon,
    rankBadgeIcon,
} from "@/components/blocks/dashboard/rankBadge"
import { StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One normalised leaderboard row (the container maps its query data into this). */
export interface LeaderboardRow {
    /** React key + stable id. */
    key: string
    /** 1-based rank ΓÇö Γëñ3 renders a place medal, else the number. */
    rank: number
    /** Display username (null ΓåÆ dash). */
    username: string | null
    /** Avatar URL (null ΓåÆ generated fallback). */
    avatar?: string | null
    /** Pre-formatted trailing value (e.g. "640 pts" / "1420 XP"). */
    valueLabel: React.ReactNode
    /** True ΓåÆ highlight as the viewer (accent value + `meLabel` suffix). */
    isMe?: boolean
    /** Profile link target; omit ΓåÆ the identity is non-clickable. */
    profileHref?: string
    /** Context action at the far right (rank-delta caret / follow button). */
    trailing?: React.ReactNode
    /**
     * Optional left band (`SurfaceListCardItem.withVerdict`, `card.md` ┬º3i) ΓÇö a DATA
     * signal on this row (e.g. the weekly cohort's promote/demote zone). Pass the
     * canonical {@link VerdictBand} (`variant`/`color`) ΓÇö NOT a free-form `className`,
     * which `verdictBandClassName` silently ignores (was the "invisible border" bug).
     */
    verdict?: VerdictBand
}

/** The viewer's own standing shown as the card's header line. */
export interface LeaderboardStanding {
    /** Viewer's rank ΓÇö drives the leading {@link IconTile} badge (medal Γëñ3 / cup 4+). */
    rank: number
    /** Primary line (e.g. "Rank #1 ┬╖ top 20%"). */
    primary: React.ReactNode
    /** Secondary muted line (e.g. "640 pts ┬╖ Resets in 1 day 18 hours"). */
    secondary?: React.ReactNode
}

/** Props for {@link LeaderboardListCard}. */
export interface LeaderboardListCardProps extends WithClassNames<undefined> {
    /**
     * Bare mode ΓÇö skip the {@link LabeledCard} frame (`title`/`onSeeMore` ignored) and
     * render just the standing + list. For a full page that already has its own
     * `PageHeader` (the course leaderboard); the dashboard cards leave it off.
     */
    bare?: boolean
    /** Card label (LabeledCard heading). Ignored when `bare`. */
    title?: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label. */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). */
    standing?: LeaderboardStanding
    /**
     * Optional node between the standing and the list ΓÇö e.g. a `Podium` on a spacious
     * page (course leaderboard). Dashboard cards omit it (compact, no podium).
     */
    topSlot?: React.ReactNode
    /** The ranked rows (top-N slice; when a podium is in `topSlot`, pass rank 4+). */
    rows: Array<LeaderboardRow>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfRow?: LeaderboardRow
    /** Ellipsis label above the pinned self-row (e.g. "41 more people"). */
    ellipsisLabel?: React.ReactNode
    /** "You" suffix appended to the viewer's own row name. */
    meLabel?: React.ReactNode
}

/**
 * The ONE shared render for a dashboard leaderboard preview ΓÇö a {@link LabeledCard}
 * with the viewer's own standing (rank-driven {@link IconTile} badge: medal for the
 * podium, cup below) over a bordered {@link SurfaceListCard} of ranked rows (top-3
 * wear place medals). Both the weekly "Weekly league" and the global "Top learners"
 * cards map their data into this, so they render IDENTICALLY (teacher 2026-07-17 "2
 * identical sections"); only the per-context `trailing` slot (rank-delta caret vs follow)
 * and the emergent badge differ. Presentational + props-only; containers own the fetch.
 *
 * @param props - {@link LeaderboardListCardProps}
 */
export const LeaderboardListCard = ({
    bare = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    topSlot,
    rows,
    selfRow,
    ellipsisLabel,
    meLabel,
    className,
}: LeaderboardListCardProps) => {
    /** Render one row (shared by the ranked list and the pinned self-row). */
    const renderRow = (row: LeaderboardRow) => {
        const displayName = row.isMe && row.username && meLabel
            ? `${row.username} ┬╖ ${meLabel}`
            : (row.username ?? "")
        const identity = (
            <UserCell
                username={displayName}
                avatar={row.avatar ?? undefined}
                isOwnRow={row.isMe }
            />
        )
        return (
            <SurfaceListCardItem key={row.key} withVerdict={row.verdict}>
                <div className="flex items-center gap-3">
                    {/* top-3 ΓåÆ place medal (≡ƒÑç≡ƒÑê≡ƒÑë); rank 4+ ΓåÆ plain number. Number matches the
                        medal's w-6 CENTERED slot (teacher 2026-07-17 "4 and 5 still misaligned") at the same
                        text-sm foreground as the name (same-row same-size, `visual-hierarchy`). */}
                    {row.rank <= 3 ? (
                        <span className="flex w-6 shrink-0 items-center justify-center">
                            {placeMedalIcon(row.rank)}
                        </span>
                    ) : (
                        <span className="flex w-6 shrink-0 items-center justify-center text-sm text-foreground">
                            {row.rank}
                        </span>
                    )}
                    {row.profileHref ? (
                        <Link
                            href={row.profileHref}
                            className="flex min-w-0 flex-1 items-center text-foreground no-underline transition-opacity hover:opacity-60"
                        >
                            {identity}
                        </Link>
                    ) : (
                        <div className="flex min-w-0 flex-1 items-center">{identity}</div>
                    )}
                    {/* value = meta ΓåÆ always muted + right-aligned tabular so the XP column
                        lines up across rows (teacher 2026-07-17: accent moves to the NAME, value
                        stays muted). */}
                    <Typography
                        type="body-sm"
                        color="muted"
                        className="shrink-0 text-right tabular-nums"
                    >
                        {row.valueLabel}
                    </Typography>
                    {row.trailing ? (
                        <div className="flex shrink-0 items-center">{row.trailing}</div>
                    ) : null}
                </div>
            </SurfaceListCardItem>
        )
    }

    const contentItems = [
        ...(standing
            ? [() => (
                <div className="flex items-center gap-3">
                    <IconTile icon={rankBadgeIcon(standing.rank)} tone="neutral" size="sm" />
                    <div className="flex min-w-0 flex-col">
                        <Typography type="body-sm" weight="bold" truncate>
                            {standing.primary}
                        </Typography>
                        {standing.secondary ? (
                            <Typography type="body-xs" color="muted">
                                {standing.secondary}
                            </Typography>
                        ) : null}
                    </div>
                </div>
            )]
            : []),
        ...(topSlot ? [() => <>{topSlot}</>] : []),
        ...(rows.length > 0 || selfRow
            ? [() => (
                <SurfaceListCard bordered>
                    {rows.map(renderRow)}
                    {selfRow ? (
                        <>
                            <SurfaceListCardItem>
                                <div className="flex min-h-8 items-center gap-3">
                                    <span className="flex w-6 shrink-0 items-center justify-center text-base leading-none tracking-widest text-muted">
                                        Γï»
                                    </span>
                                    <Typography type="body-sm" color="muted">
                                        {ellipsisLabel}
                                    </Typography>
                                </div>
                            </SurfaceListCardItem>
                            {renderRow(selfRow)}
                        </>
                    ) : null}
                </SurfaceListCard>
            )]
            : []),
    ]

    // bare ΓåÆ the page owns the frame (PageHeader); dashboard cards keep the LabeledCard
    if (bare) {
        return (
            <div className={cn("flex flex-col gap-3", className)}>
                {contentItems.map((Item, index) => (
                    <Item key={index} />
                ))}
            </div>
        )
    }

    return (
        <LabeledCard
            identity={{ tier: "block", component: "LeaderboardListCard" }}
            // `title` is only ever omitted in `bare` mode, which already returned above ΓÇö
            // the fallback here is a type-safety guard, not a real state either caller hits.
            label={title ?? ""}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
        >
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Standing, optional podium, and cohort list are peer sections in one leaderboard ΓÇö not block-boundary, because they stay inside one card group."
                items={contentItems}
            />
        </LabeledCard>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import {
    LeaderboardListCard,
    LeaderboardRow,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import type { QueryMyLeagueData } from "@/modules/api/graphql/queries/types/league"

/** How many top-of-cohort rows to show before truncating (no inner scroll). */
const TOP_ROWS = 5

/** Props for {@link LeagueCardContent}. */
export interface LeagueCardContentProps {
    /** The resolved (non-null) weekly-league standing ΓÇö supplied by the container. */
    data: QueryMyLeagueData
    /** Kept for API compatibility with the container; the card is always framed now. */
    framed?: boolean
}

/**
 * DashboardPage "Weekly League" card ΓÇö maps the resolved weekly-league data into the shared
 * {@link LeaderboardListCard} (standing header with a rank-driven medal/cup badge, then
 * the top cohort as a medal-ranked list with a rank-movement caret per row). Renders
 * identically to the global {@link import("../../TopLearners").TopLearners} card; only
 * the trailing slot (caret vs follow) differs (instructor's call, 2026-07-17, "two identical sections").
 *
 * @param props - {@link LeagueCardContentProps}
 */
export const LeagueCardContent = ({
    data}: LeagueCardContentProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const me = useAppSelector((state) => state.user.user)

    /** Open the full leaderboard/league page (see-more link in the card header). */
    const onSeeMore = useCallback(
        () => router.push(pathConfig().locale(locale).league().build()),
        [router, locale],
    )

    /** Hours/days left until the weekly reset (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            const remaining = Math.max(0, new Date(data.weekEndAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [data],
    )

    const total = data.entries.length
    const isMine = (username: string | null) => Boolean(me?.username) && username === me?.username

    const myEntry = me?.username
        ? data.entries.find((entry) => entry.username === me.username)
        : undefined
    const myPercent = myEntry ? Math.max(1, Math.ceil((myEntry.rank / total) * 100)) : null

    // top slice INCLUDING the viewer in place; a pinned self-row follows when the
    // viewer sits below it.
    const topRows = data.entries.slice(0, TOP_ROWS)
    const viewerInTop = myEntry
        ? topRows.some((entry) => entry.userGlobalId === myEntry.userGlobalId)
        : true
    const showSelfRow = Boolean(myEntry) && !viewerInTop
    const hiddenBetween = showSelfRow && myEntry
        ? Math.max(0, myEntry.rank - topRows.length - 1)
        : 0

    /** Map a cohort entry ΓåÆ a normalised {@link LeaderboardRow} (caret trailing + movement band). */
    const toRow = (entry: typeof data.entries[number]): LeaderboardRow => {
        // band = weekly rank MOVEMENT (mirrors the Γû┤Γû╛ `RankDeltaCaret`), NOT the cohort
        // promote/demote zone ΓÇö a per-row signal that ALWAYS shows (no cohort-size gate,
        // so a small seed cohort still renders it): climbed ΓåÆ success, dropped ΓåÆ danger,
        // unchanged / no last-week baseline ΓåÆ no band (instructor's call, 2026-07-17: the DashboardPage
        // preview always shows it; unlike the /league page, which uses the promote/demote zone instead).
        const delta = entry.rankDelta ?? 0
        return {
            key: entry.userGlobalId,
            rank: entry.rank,
            username: entry.username,
            avatar: entry.avatar,
            valueLabel: t("DashboardPage.league.points", { count: entry.weekPoints }),
            isMe: isMine(entry.username),
            profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
            trailing: <RankDeltaCaret delta={entry.rankDelta} className="w-8 justify-end" />,
            verdict: delta !== 0
                ? { enable: true, variant: delta > 0 ? "success" : "danger" }
                : undefined,
        }
    }

    return (
        <LeaderboardListCard
            title={t("DashboardPage.league.title")}
            onSeeMore={onSeeMore}
            seeMoreLabel={t("DashboardPage.league.seeMore")}
            standing={myEntry && myPercent !== null ? {
                rank: myEntry.rank,
                primary: t("DashboardPage.myProfile.rankLine", {
                    rank: myEntry.rank,
                    percent: myPercent,
                }),
                secondary: (
                    <>
                        {t("DashboardPage.league.points", { count: myEntry.weekPoints })}
                        {` ┬╖ ${t("DashboardPage.league.resetIn", {
                            days: countdown.days,
                            hours: countdown.hours,
                        })}`}
                    </>
                ),
            } : undefined}
            rows={topRows.map(toRow)}
            selfRow={showSelfRow && myEntry ? toRow(myEntry) : undefined}
            ellipsisLabel={hiddenBetween > 0
                ? t("DashboardPage.league.othersCount", { count: hiddenBetween })
                : undefined}
            meLabel={t("DashboardPage.league.you")}
        />
    )
}

"use client"

import React from "react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import {
    SurfaceListCard,
    SurfaceListCardItem,
} from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import {
    LeaderboardListCard,
    type LeaderboardRow,
    type LeaderboardStanding,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import { RankDeltaCaret } from "@/components/blocks/profile/RankDeltaCaret"
import { StackH, StackV } from "@/components/frames/Stack"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"

/** Number of placeholder cohort rows the co-located skeleton shows (mirrors the capped top rows). */
const SKELETON_ROWS = 5

/**
 * One resolved cohort entry, already mapped + translated by the connected {@link
 * import("./index").LeagueCard} ΓÇö the presentational half turns it into a {@link LeaderboardRow}.
 */
export interface LeagueCardEntry {
    /** React key + stable id. */
    userGlobalId: string
    /** 1-based rank ΓÇö Γëñ3 renders a place medal, else the number. */
    rank: number
    /** Display username (null ΓåÆ dash). */
    username: string | null
    /** Avatar URL (null ΓåÆ generated fallback). */
    avatar?: string | null
    /** Rank movement vs last week (mirrors the Γû┤Γû╛ {@link RankDeltaCaret}). */
    rankDelta: number | null
    /** True ΓåÆ highlight as the viewer (accent name + `meLabel` suffix). */
    isMe: boolean
    /** Profile link target. */
    profileHref: string
    /** Already-translated "N pts" label for this entry. */
    pointsLabel: string
}

/** Props for {@link _LeagueCard} ΓÇö presentational; all data/text resolved, no fetch/store/i18n. */
export interface LeagueCardProps extends WithClassNames<undefined> {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no cohort placement ΓåÆ the empty message. */
    isEmpty?: boolean
    /**
     * Kept for API compatibility with the container; the card is always framed
     * (a `LabeledCard`, via {@link LeaderboardListCard}) now.
     */
    framed?: boolean
    /** League title (already translated). */
    title: string
    /**
     * Help text for the title's tooltip (already translated) ΓÇö currently unused: the
     * label row has no slot for a decoration once `label` became plain text. Kept for
     * API compatibility until a real "labelAdornment" slot exists.
     */
    titleHelp: string
    /** "See more" handler (opens the full board). */
    onSeeMore?: () => void
    /** "See more" label (already translated). */
    seeMoreLabel?: string
    /** The viewer's own standing header line (omit when they have no rank). Text pre-resolved. */
    standing?: LeaderboardStanding
    /** Top-of-cohort entries (already sliced by the container). */
    entries?: Array<LeagueCardEntry>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfEntry?: LeagueCardEntry
    /** Ellipsis label above the pinned self-row (already translated). */
    ellipsisLabel?: string
    /** "You" suffix appended to the viewer's own row name (already translated). */
    meLabel?: string
    /** Empty-state title (already translated). */
    emptyTitle: string
    /** Empty-state description (already translated). */
    emptyDescription: string
}

/** Map one resolved {@link LeagueCardEntry} ΓåÆ a {@link LeaderboardRow} (caret trailing + movement band). */
const toRow = (entry: LeagueCardEntry): LeaderboardRow => ({
    key: entry.userGlobalId,
    rank: entry.rank,
    username: entry.username,
    avatar: entry.avatar,
    valueLabel: entry.pointsLabel,
    isMe: entry.isMe,
    profileHref: entry.profileHref,
    trailing: <RankDeltaCaret delta={entry.rankDelta} className="w-8 justify-end" />,
    verdict: entry.rankDelta
        ? { enable: true, variant: entry.rankDelta > 0 ? "success" : "danger" }
        : undefined,
})

/**
 * DashboardPage "Weekly League" card ΓÇö the presentational half of {@link import("./index").LeagueCard}.
 * Renders identically to the global {@link import("../TopLearners").TopLearners} card through the
 * shared {@link LeaderboardListCard}; only the trailing slot (caret vs follow) differs (instructor's
 * call, 2026-07-17, "two identical sections").
 *
 * {@link LeaderboardListCard} takes no `isSkeleton` of its own (it owns the label + standing header
 * + row list as one opaque block), so the LOADING branch mirrors its exact structure by hand, right
 * at this call site ΓÇö the same `LabeledCard` label, standing header, and bordered `SurfaceListCard`
 * rows, with `Skeleton.*` swapped in for every content node (`loading-and-skeleton.md` ┬º3/┬º6). This
 * is co-located (one file, one call site), not a separate skeleton component to keep in sync.
 *
 * @param props - {@link LeagueCardProps}
 */
export const _LeagueCard = ({
    isSkeleton = false,
    isEmpty = false,
    title,
    onSeeMore,
    seeMoreLabel,
    standing,
    entries = [],
    selfEntry,
    ellipsisLabel,
    meLabel,
    emptyTitle,
    emptyDescription,
}: LeagueCardProps) => {
    // settled with no cohort placement (BLOCK-8) ΓåÆ translated empty state (join hint), not self-hide
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty title={emptyTitle} description={emptyDescription} />
    }

    if (isSkeleton) {
        return (
            <LabeledCard

                // `label` is plain text now (never a built element), and `title` is already
                // known statically (translated up front, not fetched) ΓÇö showing it for real
                // instead of shimmering it is strictly more correct, not just a workaround.
                label={title}
            >
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Skeleton standing header and cohort rows are peer sections in one league card ΓÇö not block-boundary."
                    items={[
                        () => (
                            <StackH gap={4} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center" items={[
                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                    () => (
                                        <StackV gap={2} principle="title-subtitle"
                                            explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                                            classNames={["min-w-0", "flex-1"]} items={[
                                                () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                            ]} />
                                    ),
                                ]} />
                        ),
                        () => (
                            <SurfaceListCard bordered>
                                {Array.from({ length: SKELETON_ROWS }, (_row, index) => (
                                    <SurfaceListCardItem key={index}>
                                        <StackH gap={4} principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            align="center" items={[
                                                () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                                () => <Skeleton.Avatar size="sm" />,
                                                () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                                () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                                () => <Skeleton className="h-4 w-8 shrink-0 rounded-sm" />,
                                            ]} />
                                    </SurfaceListCardItem>
                                ))}
                            </SurfaceListCard>
                        ),
                    ]}
                />
            </LabeledCard>
        )
    }

    return (
        <LeaderboardListCard

            // `title` forwards into `LabeledCard.label`, plain text now (never a built
            // element) ΓÇö the `InfoTooltip` decoration has no slot to ride any more
            // (mirrors the same drop in `LeagueCardContent`); `titleHelp` is unused here
            // pending a real "labelAdornment"-style slot on `LabeledCard`.
            title={title}
            onSeeMore={onSeeMore}
            seeMoreLabel={seeMoreLabel}
            standing={standing}
            rows={entries.map(toRow)}
            selfRow={selfEntry ? toRow(selfEntry) : undefined}
            ellipsisLabel={ellipsisLabel}
            meLabel={meLabel}
        />
    )
}

"use client"

import React, { useCallback, useMemo } from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyLeagueSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyLeagueSwr"
import type { QueryMyLeagueEntryData } from "@/modules/api/graphql/queries/types/league"
import {
    _LeagueCard,
    type LeagueCardEntry,
} from "./component"

/** How many top-of-cohort rows to show before truncating (no inner scroll). */
const TOP_ROWS = 5

/** Props for {@link LeagueCard}. */
export interface LeagueCardProps {
    /**
     * When true, render the league inside a `LabeledCard` (title as a Label OUTSIDE
     * the card) instead of the flat inline heading ΓÇö used on the DashboardPage Community
     * tab so it matches the other LabeledCard sections. Defaults to the flat layout
     * (the standalone /league page). Kept for API compatibility with `_LeagueCard`;
     * the card is always framed now.
     */
    framed?: boolean
}

/** Resolve one query entry into the display-ready {@link LeagueCardEntry} the presentational half renders. */
const toEntry = (
    entry: QueryMyLeagueEntryData,
    locale: string,
    meUsername: string | undefined,
    pointsLabel: string,
): LeagueCardEntry => ({
    userGlobalId: entry.userGlobalId,
    rank: entry.rank,
    username: entry.username,
    avatar: entry.avatar,
    rankDelta: entry.rankDelta,
    isMe: Boolean(meUsername) && entry.username === meUsername,
    profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
    pointsLabel,
})

/**
 * Compact weekly-league card for the DashboardPage ΓÇö the CONNECTED half: self-fetches the
 * league leaf query, computes the async decisions and every derived value (standing,
 * top rows, the pinned self-row), resolves all i18n, and hands them to the
 * presentational {@link _LeagueCard}. `isSkeleton` uses the nullish form so the shimmer
 * holds until data actually arrives (and never on a falsy-but-valid value). See
 * `tiers/split.md`.
 * @param props - {@link LeagueCardProps}
 */
export const LeagueCard = ({
    framed = false}: LeagueCardProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const me = useAppSelector((state) => state.user.user)
    const { data, isLoading } = useQueryMyLeagueSwr()

    // first load, nothing in hand ΓåÆ shimmer (same condition the pre-split `AsyncContent` used)
    const isSkeleton = data === null || data === undefined || isLoading
    // not yet placed in a cohort ΓåÆ translated empty state (join hint), not self-hide
    const isEmpty = data === null || data === undefined || data.entries.length === 0

    /** Open the full leaderboard/league page (see-more link in the card header). */
    const onSeeMore = useCallback(
        () => router.push(pathConfig().locale(locale).league().build()),
        [router, locale],
    )

    const total = data?.entries.length ?? 0
    const myEntry = data && me?.username
        ? data.entries.find((entry) => entry.username === me.username)
        : undefined
    const myPercent = myEntry ? Math.max(1, Math.ceil((myEntry.rank / total) * 100)) : null

    // top slice INCLUDING the viewer in place; a pinned self-row follows when the
    // viewer sits below it.
    const topRows = data ? data.entries.slice(0, TOP_ROWS) : []
    const viewerInTop = myEntry
        ? topRows.some((entry) => entry.userGlobalId === myEntry.userGlobalId)
        : true
    const showSelfRow = Boolean(myEntry) && !viewerInTop
    const hiddenBetween = showSelfRow && myEntry
        ? Math.max(0, myEntry.rank - topRows.length - 1)
        : 0

    /** Hours/days left until the weekly reset (computed from `weekEndAt`). */
    const countdown = useMemo(
        () => {
            if (!data) {
                return { days: 0, hours: 0 }
            }
            const remaining = Math.max(0, new Date(data.weekEndAt).getTime() - Date.now())
            return {
                days: Math.floor(remaining / 86_400_000),
                hours: Math.floor((remaining % 86_400_000) / 3_600_000),
            }
        },
        [data],
    )

    /** "N pts" label for one entry's weekly points, already translated. */
    const pointsLabel = useCallback(
        (weekPoints: number) => t("DashboardPage.league.points", { count: weekPoints }),
        [t],
    )

    return (
        <_LeagueCard
            framed={framed}
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            title={t("DashboardPage.league.title")}
            titleHelp={t("DashboardPage.league.help")}
            onSeeMore={onSeeMore}
            seeMoreLabel={t("DashboardPage.league.seeMore")}
            standing={myEntry && myPercent !== null ? {
                rank: myEntry.rank,
                primary: t("DashboardPage.myProfile.rankLine", {
                    rank: myEntry.rank,
                    percent: myPercent,
                }),
                secondary: `${pointsLabel(myEntry.weekPoints)} ┬╖ ${t("DashboardPage.league.resetIn", {
                    days: countdown.days,
                    hours: countdown.hours,
                })}`,
            } : undefined}
            entries={topRows.map((entry) => toEntry(entry, locale, me?.username, pointsLabel(entry.weekPoints)))}
            selfEntry={showSelfRow && myEntry ? toEntry(myEntry, locale, me?.username, pointsLabel(myEntry.weekPoints)) : undefined}
            ellipsisLabel={hiddenBetween > 0
                ? t("DashboardPage.league.othersCount", { count: hiddenBetween })
                : undefined}
            meLabel={t("DashboardPage.league.you")}
            emptyTitle={t("DashboardPage.league.emptyTitle")}
            emptyDescription={t("DashboardPage.league.emptyDescription")}
        />
    )
}

