import React from "react"
import { TrophyIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import {
    LeaderboardListCard,
    type LeaderboardRow,
    type LeaderboardStanding,
} from "@/components/blocks/dashboard/LeaderboardListCard"
import { StackH, StackV } from "@/components/frames/Stack"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** How many placeholder rows the co-located skeleton mirror shows (mirrors {@link import("./index").TOP_N}). */
const SKELETON_ROW_COUNT = 5

/** All display text, already localized by the connected {@link import("./index").TopLearners}; a story passes i18n keys. */
export interface TopLearnersLabels {
    title: string
    seeMoreLabel: string
    noLeadersTitle: string
    noLeadersDescription: string
    meLabel: string
}

/** Props for {@link _TopLearners} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface TopLearnersProps extends WithClassNames<undefined> {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no leaderboard entries ΓåÆ the empty message. */
    isEmpty?: boolean
    /** Opens the full leaderboard page. */
    onSeeMore?: () => void
    /** The viewer's own standing header line (rank-driven medal/cup badge). Omitted on a rankless viewer. */
    standing?: LeaderboardStanding
    /** The ranked rows (top-N slice), already mapped with their trailing follow control. */
    rows?: Array<LeaderboardRow>
    /** Pinned self-row when the viewer sits below the shown slice. */
    selfRow?: LeaderboardRow
    /** Ellipsis label above the pinned self-row (e.g. "41 more people"). */
    ellipsisLabel?: React.ReactNode
    labels: TopLearnersLabels
}

/**
 * DashboardPage "Top Learners" card ΓÇö the presentational half of {@link import("./index").TopLearners}.
 * Maps the global leaderboard into the shared `LeaderboardListCard` (standing header with a
 * rank-driven medal/cup badge over a medal-ranked list). Renders IDENTICALLY to the weekly
 * "League" `LeagueCardContent`; only the trailing slot differs ΓÇö a quiet `FollowButton` per
 * stranger row, built by the connected file into each row's `trailing`.
 *
 * `LeaderboardListCard` takes no `isSkeleton` of its own, so the loading state is mirrored right
 * here, co-located at the SAME call site ΓÇö the label + standing header + `SurfaceListCard` rows,
 * matching the real card's shape 1:1 so nothing jumps when it resolves (loading-and-skeleton.md).
 * error ΓåÆ skeleton ΓåÆ empty ΓåÆ content (BLOCK-8): error beats a stale loading flag; empty only once
 * settled. See `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch, the follow mutation,
 * and every translated string.
 *
 * @param props - {@link TopLearnersProps}
 */
export const _TopLearners = ({
    isSkeleton = false,
    isEmpty = false,
    onSeeMore,
    standing,
    rows = [],
    selfRow,
    ellipsisLabel,
    labels,
    className,
}: TopLearnersProps) => {
    if (!isSkeleton && isEmpty) {
        return (
            <AsyncContentEmpty
                identity={{ tier: "block", component: "TopLearners" }}
                icon={TrophyIcon}
                title={labels.noLeadersTitle}
                description={labels.noLeadersDescription}
            />
        )
    }

    if (isSkeleton) {
        // Hoisted so outer sibling-stack is not scanned as owning nested align decisions.
        const skeletonItems = [
            () => <Skeleton.Typography type="body-sm" width="1/3" />,
            () => (
                <StackH gap={3} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    align="center" items={[
                        () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                        () => (
                            <StackV gap={1} principle="name-handle"
                                explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                classNames={["min-w-0", "flex-1"]} items={[
                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                    () => <Skeleton.Typography type="body-xs" width="1/3" />,
                                ]} />
                        ),
                    ]} />
            ),
            () => (
                <SurfaceListCard bordered>
                    {Array.from({ length: SKELETON_ROW_COUNT }, (_row, index) => (
                        <SurfaceListCardItem key={index}>
                            <StackH gap={3} principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                align="center" items={[
                                    () => <Skeleton className="h-3 w-6 shrink-0 rounded-sm" />,
                                    () => <Skeleton.Avatar size="sm" />,
                                    () => <Skeleton.Typography type="body-sm" width="1/2" className="min-w-0 flex-1" />,
                                    () => <Skeleton className="h-3 w-10 shrink-0 rounded-sm" />,
                                    () => <Skeleton className="h-8 w-24 shrink-0 rounded-xl" />,
                                ]} />
                        </SurfaceListCardItem>
                    ))}
                </SurfaceListCard>
            ),
        ]
        return (
            <StackV
                gap={3}
                principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                identity={{ tier: "block", component: "TopLearners" }}
                items={skeletonItems}
            />
        )
    }

    return (
        <LeaderboardListCard
            className={className}
            title={labels.title}
            onSeeMore={onSeeMore}
            seeMoreLabel={labels.seeMoreLabel}
            standing={standing}
            rows={rows}
            selfRow={selfRow}
            ellipsisLabel={ellipsisLabel}
            meLabel={labels.meLabel}
        />
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    FollowButton,
} from "@/components/blocks/community/FollowButton"
import {
    pathConfig,
} from "@/resources/path"
import {
    fromGlobalId,
} from "@/modules/utils/globalId"
import type { LeaderboardRow } from "@/components/blocks/dashboard/LeaderboardListCard"
import { useMutateSetFollowSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSetFollowSwr"
import { useQueryGlobalLeaderboardSwr } from "@/hooks/swr/api/graphql/queries/useQueryGlobalLeaderboardSwr"
import { useAppSelector } from "@/redux/hooks"
import { _TopLearners } from "./component"

/** How many leaders to show. */
export const TOP_N = 5

/** Props for {@link TopLearners}. */
export type TopLearnersProps = Record<string, never>
/**
 * DashboardPage "Top Learners" card ΓÇö the CONNECTED half: fetches the global leaderboard, owns the
 * follow mutation (rows stay presentational), resolves the viewer's rank-relative slice (top-N +
 * pinned self-row), and hands the resolved shape + every translated label to the presentational
 * {@link _TopLearners}. See `tiers/split.md`.
 *
 * @param props - optional root class name (placement only)
 */
export const TopLearners = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { data, isLoading } = useQueryGlobalLeaderboardSwr()
    const me = useAppSelector((state) => state.user.user)
    // owns the follow mutation; FollowButton rows stay presentational
    const { trigger: triggerSetFollow } = useMutateSetFollowSwr()
    // globalIds the viewer follows from this card (optimistic) + in-flight set
    const [followed, setFollowed] = useState<Set<string>>(new Set())
    const [pending, setPending] = useState<Set<string>>(new Set())

    const isMine = (username: string | null) => Boolean(me?.username) && username === me?.username

    /**
     * Toggle follow/unfollow. The leaderboard exposes each user as an OPAQUE global
     * id, but `setFollow` wants the raw `users.id` ΓÇö decode it first. Flips the row
     * optimistically on success.
     */
    const onToggleFollow = useCallback(
        async (globalId: string) => {
            const rawId = fromGlobalId(globalId)?.id ?? globalId
            const currentlyFollowing = followed.has(globalId)
            setPending((current) => new Set(current).add(globalId))
            try {
                const result = await triggerSetFollow({
                    userId: rawId,
                    follow: !currentlyFollowing,
                })
                if (result?.data?.setFollow?.success) {
                    setFollowed((current) => {
                        const next = new Set(current)
                        if (currentlyFollowing) {
                            next.delete(globalId)
                        } else {
                            next.add(globalId)
                        }
                        return next
                    })
                }
            } finally {
                setPending((current) => {
                    const next = new Set(current)
                    next.delete(globalId)
                    return next
                })
            }
        },
        [followed, triggerSetFollow],
    )

    // first load, nothing in hand ΓåÆ shimmer (loading-and-skeleton.md ┬º2)
    const isSkeleton = data === null || data === undefined || isLoading
    // empty (after load) when the board has no entries
    const isEmpty = !data || data.entries.length === 0

    /** Open the full leaderboard page. */
    const onSeeMore = useCallback(
        () => router.push(pathConfig().locale(locale).league().build()),
        [router, locale],
    )

    // viewer below the shown slice ΓåÆ pin a self-row after an ellipsis
    const shown = data ? data.entries.slice(0, TOP_N) : []
    const viewerInTop = shown.some((entry) => isMine(entry.username))
    const showSelfRow = Boolean(data) && !viewerInTop

    /** Map a leaderboard entry ΓåÆ a normalised {@link LeaderboardRow} (follow trailing). */
    const toRow = (entry: NonNullable<typeof data>["entries"][number]): LeaderboardRow => {
        const mine = isMine(entry.username)
        return {
            key: entry.userGlobalId,
            rank: entry.rank,
            username: entry.username,
            avatar: entry.avatar,
            valueLabel: t("DashboardPage.league.points", { count: entry.points }),
            isMe: mine,
            profileHref: pathConfig().locale(locale).profile(entry.username ?? undefined).build(),
            trailing: mine ? undefined : (
                <FollowButton
                    quiet
                    following={followed.has(entry.userGlobalId)}
                    isPending={pending.has(entry.userGlobalId)}
                    onToggle={() => void onToggleFollow(entry.userGlobalId)}
                />
            ),
        }
    }

    // standing header + self row + ellipsis are only meaningful once `data` has settled
    const standing = data ? {
        rank: data.myRank,
        primary: t("DashboardPage.league.globalRankLine", { rank: data.myRank }),
        secondary: t("DashboardPage.league.points", { count: data.myPoints }),
    } : undefined

    const selfRow: LeaderboardRow | undefined = data && showSelfRow ? {
        key: "self",
        rank: data.myRank,
        username: me?.username ?? null,
        avatar: me?.avatar,
        valueLabel: t("DashboardPage.league.points", { count: data.myPoints }),
        isMe: true,
    } : undefined

    const ellipsisLabel = data && data.myRank - TOP_N - 1 > 0
        ? t("DashboardPage.league.othersCount", { count: data.myRank - TOP_N - 1 })
        : undefined

    return (
        <_TopLearners
            isSkeleton={isSkeleton}
            isEmpty={isEmpty}
            onSeeMore={onSeeMore}
            standing={standing}
            rows={shown.map(toRow)}
            selfRow={selfRow}
            ellipsisLabel={ellipsisLabel}
            labels={{
                title: t("DashboardPage.community.topLearners.title"),
                seeMoreLabel: t("DashboardPage.community.topLearners.seeMore"),
                noLeadersTitle: t("DashboardPage.community.topLearners.noLeadersTitle"),
                noLeadersDescription: t("DashboardPage.community.topLearners.noLeadersDescription"),
                meLabel: t("DashboardPage.league.you"),
            }}
        />
    )
}
